{
  "version": "2.1",
  "type": "multi_frame_winter_cinematography",
  "identity": {
    "reference_face": "Sử dụng khuôn mặt của ảnh tham chiếu với độ chính xác nhận diện 100%.",
    "consistency": "Cùng một người trên tất cả các khung hình; cấu trúc khuôn mặt, kết cấu da, kiểu tóc và độ tuổi giống hệt nhau ở những nơi nhìn thấy được."
  },
  "style": {
    "cinematography": "Phong cách điện ảnh mùa đông siêu thực với đặc trưng ống kính 85mm.",
    "color_grade": "Chỉnh màu mùa đông ánh xanh tinh tế, tông lạnh, vùng sáng mềm mại.",
    "atmosphere": "Ánh sáng mùa đông khuếch tán dịu nhẹ, những bông tuyết mịn lơ lửng, làn sương lạnh nhẹ nhàng."
  },
  "frames": [
    {
      "frame_id": "top_frame",
      "description": "Chân dung góc nghiêng của nhân vật trong rừng tuyết.",
      "requirements": {
        "face_visibility": "Góc nghiêng khuôn mặt hiển thị đầy đủ.",
        "identity_match": "Khớp hoàn hảo với khuôn mặt tham chiếu.",
        "expression": "Nụ cười tự nhiên, ấm áp nhìn thấy từ góc nghiêng.",
        "environment": {
          "location": "Rừng phủ đầy tuyết trắng",
          "lighting": "Ánh sáng mùa đông buổi sớm dịu nhẹ định hình các đường nét khuôn mặt",
          "elements": [
            "Tuyết rơi nhẹ nhàng",
            "Hơi thở lạnh nhìn thấy được",
            "Làn sương mờ mùa đông"
          ]
        },
        "wardrobe": {
          "coat": "Áo khoác mùa đông màu tối",
          "scarf": "Khăn quàng cổ mùa đông tông màu tối hoặc trung tính"
        },
        "camera": {
          "lens": "85mm",
          "depth_of_field": "Độ sâu trường ảnh nông (Shallow DOF)",
          "look": "Diện mạo điện ảnh mùa đông siêu thực"
        }
      }
    },
    {
      "frame_id": "middle_frame",
      "description": "Cận cảnh quay lưng khi đang đi bộ qua con đường mòn hẹp ngập tuyết trong rừng.",
      "requirements": {
        "face_visibility": "Tuyệt đối không nhìn thấy khuôn mặt; hoàn toàn quay lưng lại.",
        "identity_cues": "Vóc dáng cơ thể, tư thế và trang phục phải thể hiện rõ ràng cùng một người.",
        "environment": {
          "location": "Đường mòn phủ tuyết hẹp trong rừng",
          "forbidden_elements": ["Không có cổng torii"],
          "trees": "Những hàng cây cao trơ trụi hơi uốn cong, tạo thành một hành lang tuyết tự nhiên",
          "atmosphere": "Sự tĩnh lặng mùa đông thanh bình, yên ắng cùng tuyết rơi"
        },
        "wardrobe": {
          "coat": "Cùng chiếc áo khoác mùa đông màu tối như khung hình trên",
          "scarf": "Cùng chiếc khăn quàng cổ"
        },
        "camera": {
          "lens": "85mm",
          "shot_type": "Cận cảnh từ phía sau",
          "depth_of_field": "Hậu cảnh mờ với độ sâu trường ảnh nông (DOF nông)"
        }
      }
    },
    {
      "frame_id": "bottom_frame",
      "description": "Đặc tả cận cảnh ngước nhìn lên bầu trời với những bông tuyết mùa đông đang rơi.",
      "requirements": {
        "face_visibility": "Đặc tả cận cảnh cực gần (Extreme close-up), khuôn mặt hiển thị đầy đủ.",
        "identity_match": "Khớp chính xác với khuôn mặt tham chiếu.",
        "expression": "Nụ cười dịu dàng, ấm áp khi nhìn ngước lên trên.",
        "environment": {
          "elements": [
            "Những bông tuyết rơi xung quanh nhưng KHÔNG chạm vào mặt",
            "Tuyết chỉ xuất hiện ở tiền cảnh và hậu cảnh",
            "Không nhìn thấy luồng hơi thở hay khói miệng",
            "Làn sương mùa đông dịu nhẹ trong không gian xung quanh"
          ]
        },
        "camera": {
          "lens": "85mm",
          "depth_of_field": "Rất nông",
          "detail": "Độ chân thực cao, kết cấu da sắc nét, các bông tuyết được lấy nét có chọn lọc"
        },
        "lighting": "Ánh sáng mùa đông mềm mại với những ánh phản chiếu xanh tinh tế"
      }
    }
  ],
  "global_constraints": {
    "identity": "Khuôn mặt tham chiếu phải được tái tạo hoàn hảo trong tất cả các khung hình nhìn thấy mặt.",
    "continuity": "Ánh sáng, bảng màu mùa đông, đặc tính ống kính và bầu không khí phải duy trì nhất quán trên tất cả các khung hình.",
    "realism_level": "Siêu chân thực, chuẩn điện ảnh cao cấp."
  }
}
